(function(){'use strict';
/* JAH The Classical Mechanics generator — jahdb-classical-mechanics-1.0.
   Property of Justin Addam Higgins (JAH).
   Deterministic: same seed, same record. */
var PREFIX='JAH-CLMEC-';
var FIELDS=["Foundations","Compounded","Advanced"];
var TOPICS=[{"tier": "Foundations", "g": "Fundamentals", "title": "What Is Classical Mechanics", "desc": "Classical mechanics describes the motion of macroscopic objects: how forces change motion, how energy and momentum are conserved, and how systems evolve predictably. From thrown balls to orbiting planets to engineered machines, it is the physics of the everyday scale.\nIts formulations ascend in power: Newtonian (forces), Lagrangian (energies, generalized coordinates), Hamiltonian (phase space, the bridge to quantum mechanics). Valid where speeds are far below light and sizes far above atoms - within which it is essentially exact.", "how": "Choose the formulation: Newton for simple force problems, Lagrange for constraints and generalized coordinates, Hamilton for phase-space and conservation structure. Check the regime: v << c and action >> ħ, else use relativity or quantum mechanics.", "keys": ["Motion of macroscopic objects, predictably.", "Newton → Lagrange → Hamilton: ascending power.", "Valid for v << c, sizes >> atoms.", "Forces, energies, phase space: three views.", "Essentially exact within its regime."], "reqs": ["Regime check (v << c, macroscopic).", "Formulation matched to problem.", "Coordinate system chosen."], "stds": ["SI units throughout.", "Vectors distinguished from scalars."], "cites": ["Goldstein H et al. Classical Mechanics. 3rd ed. Addison-Wesley; 2001.", "Taylor JR. Classical Mechanics. University Science; 2005."], "demo": "#!/usr/bin/env python3\n\"\"\"Regime check: classical vs relativistic/quantum.\"\"\"\ndef regime(v_m_s, size_m):\n    if v_m_s > 0.1*3e8: return \"relativistic\"\n    if size_m < 1e-9: return \"quantum\"\n    return \"classical\"\nprint(\"  car:\", regime(30, 4), \"| electron in atom:\", regime(2e6, 1e-10))\n"}, {"tier": "Foundations", "g": "Kinematics", "title": "Kinematics: Position, Velocity, Acceleration", "desc": "Kinematics describes motion without asking why: position x(t), velocity v = dx/dt, acceleration a = dv/dt. Constant acceleration gives the SUVAT equations: v = v₀ + at, x = x₀ + v₀t + ½at², v² = v₀² + 2aΔx - the workhorses of projectile and falling-body problems.\nVectors matter in 2D/3D: projectile motion separates into independent horizontal (constant v) and vertical (constant g) components. Galileo's inclined planes founded it; calculus made it exact.", "how": "Write x(t), differentiate for v and a (or integrate upward). For constant a, use SUVAT. Split projectiles into x/y components; solve time from vertical motion, range from horizontal. Check units and reasonableness of every answer.", "keys": ["v = dx/dt; a = dv/dt.", "SUVAT for constant acceleration.", "Projectiles: independent x/y components.", "Galileo founded it; calculus exacted it.", "Differentiate down, integrate up."], "reqs": ["Position function or initial conditions.", "Constant-a check for SUVAT.", "Coordinate axes defined."], "stds": ["SI: m, m/s, m/s².", "Vectors with components stated."], "cites": ["Taylor JR. Classical Mechanics. University Science; 2005.", "Halliday D et al. Fundamentals of Physics. 12th ed. Wiley; 2021."], "demo": "#!/usr/bin/env python3\n\"\"\"Projectile range: 45° maximizes.\"\"\"\nimport math\ndef projectile_range(v0, deg, g=9.81):\n    return v0**2*math.sin(2*math.radians(deg))/g\nfor d in (30, 45, 60):\n    print(f\"  {d}°: range = {projectile_range(20, d):.1f} m\")\n"}, {"tier": "Foundations", "g": "Dynamics", "title": "Newton's Laws of Motion", "desc": "First: objects keep their velocity unless forced (inertia, defining inertial frames). Second: F = ma - force changes momentum (F = dp/dt, the general form). Third: every action has an equal, opposite reaction on the other body.\nPublished in the Principia (1687), they unified earthly and celestial motion. They fail at high speed (relativity), small scales (quantum), and in accelerating frames (fictitious forces appear) - but within their domain they are law.", "how": "Draw free-body diagrams: every force on the body, none it exerts. Apply F = ma per component; use F = dp/dt for variable mass (rockets). Identify third-law pairs across two bodies - never on one diagram. Check inertial frame or add fictitious forces.", "keys": ["1st: inertia defines inertial frames.", "2nd: F = ma (F = dp/dt general).", "3rd: action-reaction pairs on different bodies.", "Principia 1687 unified heaven and earth.", "Free-body diagrams first, always."], "reqs": ["Free-body diagram.", "Inertial frame (or fictitious forces).", "Mass (constant or variable)."], "stds": ["Forces in newtons.", "Third-law pairs across bodies."], "cites": ["Newton I. Principia. 1687.", "Taylor JR. Classical Mechanics. University Science; 2005."], "demo": "#!/usr/bin/env python3\n\"\"\"F = ma across masses.\"\"\"\ndef accel(F, m):\n    return F/m\nfor m in (1, 10, 1000):\n    print(f\"  F=100 N, m={m} kg: a = {accel(100, m):.2f} m/s²\")\n"}, {"tier": "Foundations", "g": "Dynamics", "title": "Forces: Friction, Tension, Normal", "desc": "Contact forces: the normal force (perpendicular, prevents interpenetration), friction (parallel, opposes relative motion - static ≤ μsN, kinetic = μkN), tension (pulls along ropes, massless ropes transmit undiminished), springs (Hooke: F = -kx).\nFriction's laws (Amontons-Coulomb): proportional to normal force, independent of contact area, static exceeds kinetic. Inclined-plane problems combine all four - the standard dynamics workout.", "how": "Resolve forces along/perpendicular to motion. Apply friction inequalities (static is an upper bound - solve, then check). Treat massless ropes/pulleys as tension transmitters. Use Hooke for springs within elastic limit.", "keys": ["Normal: perpendicular; friction: parallel, opposes slip.", "Static ≤ μsN; kinetic = μkN.", "Massless ropes transmit tension undiminished.", "Springs: F = -kx.", "Friction independent of contact area."], "reqs": ["μs, μk for surfaces.", "Normal force computed.", "Static-vs-sliding check."], "stds": ["μ dimensionless.", "Forces in newtons."], "cites": ["Halliday D et al. Fundamentals of Physics. 12th ed. Wiley; 2021.", "Taylor JR. Classical Mechanics. University Science; 2005."], "demo": "#!/usr/bin/env python3\n\"\"\"Block on incline: slip or stick?\"\"\"\nimport math\ndef slips(deg, mu_s):\n    return math.tan(math.radians(deg)) > mu_s\nfor deg in (20, 30, 40):\n    print(f\"  {deg}°, μs=0.5: {\"slips\" if slips(deg, 0.5) else \"sticks\"}\")\n"}, {"tier": "Foundations", "g": "Energy", "title": "Work and Kinetic Energy", "desc": "Work W = ∫F·dx - force through distance. The work-energy theorem: net work equals change in kinetic energy (W_net = ΔK, K = ½mv²). It turns dynamics into bookkeeping: speeds from forces without tracking time.\nPower P = dW/dt = F·v is the rate. Conservative forces (gravity, springs) have path-independent work - enabling potential energy; non-conservative (friction) dissipate as heat.", "how": "Compute work by integration (or F·d for constant forces). Apply W_net = ΔK to find speeds. Distinguish conservative (path-independent, potential exists) from non-conservative (dissipative). Use power for rate questions (engines, athletes).", "keys": ["W = ∫F·dx; W_net = ΔK.", "K = ½mv².", "Conservative: path-independent work.", "Friction dissipates; gravity stores.", "Power = F·v."], "reqs": ["Force vs displacement.", "Conservative check.", "Mass and speeds."], "stds": ["Work/energy in joules.", "Power in watts."], "cites": ["Taylor JR. Classical Mechanics. University Science; 2005.", "Halliday D et al. Fundamentals of Physics. 12th ed. Wiley; 2021."], "demo": "#!/usr/bin/env python3\n\"\"\"Work-energy: speed after falling.\"\"\"\ndef v_fall(h, g=9.81):\n    return (2*g*h)**0.5\nfor h in (1, 10, 100):\n    print(f\"  drop {h} m: v = {v_fall(h):.1f} m/s\")\n"}, {"tier": "Foundations", "g": "Energy", "title": "Potential Energy and Conservation", "desc": "Conservative forces get potentials: gravity U = mgh (near Earth), springs U = ½kx², general U from F = -∇U. Mechanical energy E = K + U is conserved when only conservative forces work - the great simplifier.\nPotential-energy curves reveal motion qualitatively: turning points where E = U, equilibria where dU/dx = 0 (minima stable, maxima unstable). Roller coasters, orbits, and molecular vibrations all read from U(x).", "how": "Choose the zero of U conveniently; write E = K + U = const. Find turning points (K = 0) and equilibria (dU/dx = 0, stability from d²U/dx²). Include non-conservative work as ΔE = W_nc. Sketch U(x) before calculating - qualitative insight first.", "keys": ["U from F = -∇U; E = K + U conserved.", "Turning points where E = U.", "Minima stable, maxima unstable.", "U(x) curves reveal motion qualitatively.", "Non-conservative work changes E."], "reqs": ["Potential function.", "Total energy.", "Conservative-force check."], "stds": ["U in joules; zero stated.", "Equilibria classified by 2nd derivative."], "cites": ["Taylor JR. Classical Mechanics. University Science; 2005.", "Goldstein H et al. Classical Mechanics. 3rd ed. Addison-Wesley; 2001."], "demo": "#!/usr/bin/env python3\n\"\"\"Turning points of a mass on a spring (E given).\"\"\"\ndef turning(E, k):\n    import math\n    return math.sqrt(2*E/k)\nprint(f\"  E=2 J, k=50 N/m: x_max = ±{turning(2, 50):.3f} m\")\n"}, {"tier": "Foundations", "g": "Momentum", "title": "Momentum and Impulse", "desc": "Momentum p = mv (F = dp/dt) is conserved when no net external force acts - a consequence of space translation symmetry (Noether). Impulse J = ∫F dt = Δp: the same momentum change from a hard brief hit or a soft long push - why airbags work.\nRockets exploit it: the Tsiolkovsky equation Δv = v_e ln(m₀/m) comes from momentum conservation with variable mass. Center of mass moves as if all mass and external forces acted there.", "how": "Apply conservation per component when F_ext = 0. Use impulse for collision forces (J = Δp, F_avg = Δp/Δt). For rockets, use Tsiolkovsky. Track the center of mass - internal forces cannot move it.", "keys": ["p = mv; conserved without external force.", "Impulse J = Δp = F_avg·Δt.", "Airbags: same Δp, longer Δt, smaller F.", "Tsiolkovsky: Δv = v_e ln(m₀/m).", "Center of mass moves by external forces only."], "reqs": ["External-force inventory.", "Masses and velocities.", "Collision time for impulse."], "stds": ["p in kg·m/s; J in N·s.", "Per-component conservation."], "cites": ["Taylor JR. Classical Mechanics. University Science; 2005.", "Tsiolkovsky KE. 1903."], "demo": "#!/usr/bin/env python3\n\"\"\"Airbag physics: force vs collision time.\"\"\"\ndef F_avg(dp, dt):\n    return dp/dt\ndp = 70*20  # 70 kg at 20 m/s\nfor dt in (0.01, 0.2):\n    print(f\"  Δt={dt} s: F_avg = {F_avg(dp, dt)/1000:.0f} kN\")\n"}, {"tier": "Foundations", "g": "Momentum", "title": "Collisions: Elastic and Inelastic", "desc": "Elastic collisions conserve kinetic energy too (billiards, gas molecules); inelastic convert some to heat/deformation; perfectly inelastic stick together (maximal KE loss, momentum still conserved). 1D elastic: relative speed reverses; equal masses exchange velocities.\nThe center-of-mass frame simplifies: total momentum zero, symmetric scattering. Rutherford scattering (alpha particles off gold) is elastic Coulomb collision - the experiment that found the nucleus.", "how": "Write momentum conservation always; add energy conservation only if elastic. For 1D elastic, use the relative-velocity reversal shortcut. Transform to CM frame for 2D scattering; Rutherford's formula gives the angular distribution for Coulomb collisions.", "keys": ["Momentum always conserved; KE only if elastic.", "Perfectly inelastic: stick, maximal KE loss.", "Equal masses, 1D elastic: velocities exchange.", "CM frame symmetrizes collisions.", "Rutherford scattering found the nucleus."], "reqs": ["Elastic vs inelastic identified.", "Masses and initial velocities.", "Frame specified."], "stds": ["Velocities with signs/directions.", "KE loss quantified for inelastic."], "cites": ["Taylor JR. Classical Mechanics. University Science; 2005.", "Rutherford E. Phil Mag 1911;21:669-688."], "demo": "#!/usr/bin/env python3\n\"\"\"1D elastic collision.\"\"\"\ndef collide(m1, v1, m2, v2):\n    v1p = ((m1-m2)*v1 + 2*m2*v2)/(m1+m2)\n    v2p = ((m2-m1)*v2 + 2*m1*v1)/(m1+m2)\n    return v1p, v2p\nprint(f\"  1kg@3m/s hits 1kg@0: {collide(1,3,1,0)} (exchange!)\")\n"}, {"tier": "Foundations", "g": "Rotation", "title": "Circular Motion and Centripetal Force", "desc": "Uniform circular motion: speed constant, velocity turning - centripetal acceleration a = v²/r toward center, requiring net inward force (tension, gravity, friction). It is not a new force - 'centripetal' names the role, not a separate interaction.\nCentrifugal force appears only in rotating frames (fictitious). Banked curves, orbits, and centrifuges all balance real forces against the v²/r requirement - engineering by Newton's second law in disguise.", "how": "Set ΣF_inward = mv²/r. Identify the real force playing centripetal (tension, normal, gravity, friction). For banked curves without friction, tanθ = v²/rg. Never add a 'centrifugal force' in inertial frames.", "keys": ["a = v²/r toward center.", "'Centripetal' is a role, not a force.", "Centrifugal exists only in rotating frames.", "Banked curves: tanθ = v²/rg.", "Orbits are continuous free-fall with sideways motion."], "reqs": ["Radius and speed.", "Real force providing centripetal.", "Frame (inertial) specified."], "stds": ["a in m/s²; forces in N.", "Angles in degrees/radians stated."], "cites": ["Halliday D et al. Fundamentals of Physics. 12th ed. Wiley; 2021.", "Taylor JR. Classical Mechanics. University Science; 2005."], "demo": "#!/usr/bin/env python3\n\"\"\"Centripetal acceleration examples.\"\"\"\ndef ac(v, r):\n    return v*v/r\nprint(f\"  car 20 m/s, r=50 m: {ac(20,50):.1f} m/s²\")\nprint(f\"  LEO 7800 m/s, r=6.8e6 m: {ac(7800,6.8e6):.1f} m/s²\")\n"}, {"tier": "Foundations", "g": "Gravity", "title": "Newton's Law of Universal Gravitation", "desc": "F = Gm₁m₂/r² - universal gravitation: every mass attracts every other, inverse-square. Cavendish measured G (1798, torsion balance); the law predicted Neptune (1846) from Uranus's perturbations - theory discovering a planet.\nNear Earth: g = GM/R² = 9.81 m/s². Shell theorem: spheres attract as point masses; inside a uniform shell, zero force. Tides come from gravity's gradient (differential pull), not its strength.", "how": "Apply inverse-square with point/spherical masses (shell theorem). Compute g at altitude: g(h) = g₀(R/(R+h))². Derive tides from the differential field (∝ 1/r³). Use G = 6.674×10⁻¹¹ SI.", "keys": ["F = Gm₁m₂/r², inverse-square.", "G measured by Cavendish (1798).", "Neptune predicted from perturbations (1846).", "Shell theorem: spheres act as points.", "Tides from the gradient (∝1/r³), not strength."], "reqs": ["Masses and separation.", "Spherical symmetry for shell theorem.", "G = 6.674e-11 SI."], "stds": ["G in m³/kg·s².", "g in m/s²."], "cites": ["Newton I. Principia. 1687.", "Cavendish H. Phil Trans 1798;88:469-526."], "demo": "#!/usr/bin/env python3\n\"\"\"g at altitude.\"\"\"\ndef g(h_km):\n    return 9.81*(6371/(6371+h_km))**2\nfor h in (0, 400, 35786):\n    print(f\"  h={h:5d} km: g = {g(h):.2f} m/s²\")\n"}, {"tier": "Foundations", "g": "Gravity", "title": "Kepler's Laws", "desc": "Kepler (1609-1619) from Brahe's data: (1) orbits are ellipses with the Sun at a focus; (2) equal areas in equal times (angular momentum conservation); (3) T² ∝ a³ - the harmonic law. Newton derived them all from inverse-square gravity.\nThe third law measures masses: M = 4π²a³/GT² - weighing stars, planets, and black holes. Elliptical orbits have the vis-viva equation v² = GM(2/r - 1/a) - the astrodynamicist's daily tool.", "how": "Apply T² = (4π²/GM)a³ for periods/masses. Use equal-areas (angular momentum const) for speed ratios (perihelion fastest). Compute orbital speeds with vis-viva. Derive Kepler from Newton to see the inverse-square's fingerprints.", "keys": ["Ellipses, equal areas, T² ∝ a³.", "Newton derived all three from 1/r².", "Third law weighs masses.", "vis-viva: v² = GM(2/r - 1/a).", "Angular momentum conservation = 2nd law."], "reqs": ["Semi-major axis a.", "Central mass M.", "Elliptical parameters."], "stds": ["a in m/AU; T in s/years.", "GM (μ) in m³/s²."], "cites": ["Kepler J. Astronomia Nova. 1609; Harmonices Mundi. 1619.", "Newton I. Principia. 1687."], "demo": "#!/usr/bin/env python3\n\"\"\"Kepler 3rd law: period from semi-major axis.\"\"\"\nimport math\ndef period_years(a_AU):\n    return a_AU**1.5\nfor p, a in [(\"Mercury\", 0.387), (\"Earth\", 1.0), (\"Mars\", 1.524)]:\n    print(f\"  {p:8s}: T = {period_years(a):.2f} yr\")\n"}, {"tier": "Compounded", "g": "Rotation", "title": "Rotational Kinematics", "desc": "Rotation has its own kinematics: angle θ, angular velocity ω = dθ/dt, angular acceleration α = dω/dt. Constant-α gives rotational SUVAT (ω = ω₀ + αt, etc.). Arc length s = rθ, tangential speed v = rω, tangential acceleration a_t = rα - the translation-rotation dictionary.\nRolling without slipping couples them: v_cm = rω. Vectors: ω and α point along the axis (right-hand rule) - the direction of the axis, not of motion.", "how": "Translate with s = rθ, v = rω, a_t = rα, a_c = rω². Use rotational SUVAT for constant α. Apply rolling constraint v_cm = rω (no slip). Assign ω direction by right-hand rule for vector problems.", "keys": ["θ, ω, α: the rotational triple.", "s = rθ; v = rω; a_t = rα.", "Rolling: v_cm = rω.", "ω points along the axis (right-hand rule).", "Rotational SUVAT mirrors linear."], "reqs": ["Radius.", "No-slip condition if rolling.", "Axis direction."], "stds": ["θ in radians; ω in rad/s.", "Right-hand rule for vector direction."], "cites": ["Taylor JR. Classical Mechanics. University Science; 2005.", "Halliday D et al. Fundamentals of Physics. 12th ed. Wiley; 2021."], "demo": "#!/usr/bin/env python3\n\"\"\"Rolling wheel: v_cm from ω.\"\"\"\ndef vcm(omega, r):\n    return omega*r\nprint(f\"  ω=10 rad/s, r=0.3 m: v_cm = {vcm(10, 0.3):.1f} m/s\")\n"}, {"tier": "Compounded", "g": "Rotation", "title": "Torque and Angular Momentum", "desc": "Torque τ = r × F rotates; angular momentum L = r × p (L = Iω for rigid bodies) is conserved without net torque - the figure skater spins faster pulling arms in (I drops, ω rises). τ = dL/dt mirrors F = dp/dt.\nConservation governs: planetary orbits (Kepler's 2nd law), gyroscopes, neutron-star spin-up. Precession (τ ⊥ L) makes tops nod and gyroscopes resist - the physics of bicycles and satellites.", "how": "Compute τ = rF sinφ; set τ_net = dL/dt. Conserve L per component when τ_ext = 0 (I₁ω₁ = I₂ω₂ for rigid bodies). Analyze precession: Ω = τ/L for slow tops. Check axis: L is about the chosen origin.", "keys": ["τ = r × F; L = r × p.", "L conserved without net torque.", "Skater: I drops, ω rises.", "Precession when τ ⊥ L.", "Kepler's 2nd law is L conservation."], "reqs": ["Origin for r × calculations.", "Moment of inertia or mass distribution.", "External torque inventory."], "stds": ["τ in N·m; L in kg·m²/s.", "Conservation per component."], "cites": ["Taylor JR. Classical Mechanics. University Science; 2005.", "Goldstein H et al. Classical Mechanics. 3rd ed. Addison-Wesley; 2001."], "demo": "#!/usr/bin/env python3\n\"\"\"Skater spin-up: I halves, ω doubles.\"\"\"\nI1, w1 = 4.0, 2.0\nI2 = I1/2\nprint(f\"  ω₂ = {I1*w1/I2:.1f} rad/s (L conserved)\")\n"}, {"tier": "Compounded", "g": "Rotation", "title": "Moment of Inertia", "desc": "I = ∫r²dm - mass weighted by squared distance from axis. Hoop MR², disk ½MR², sphere ⅖MR², rod (center) 1/12 ML²: shape matters enormously. Parallel-axis theorem: I = I_cm + Md² shifts axes.\nRotational kinetic energy K = ½Iω². Rolling races: the shape with smallest I/MR² wins downhill (sphere beats disk beats hoop) - energy split between translation and rotation.", "how": "Look up or integrate I for the shape/axis; shift with parallel-axis as needed. Use K = ½Iω² in energy problems; combine with ½mv² for rolling. Predict race outcomes from I/MR² ratios.", "keys": ["I = ∫r²dm: mass far from axis counts most.", "Hoop MR² > disk ½MR² > sphere ⅖MR².", "Parallel-axis: I = I_cm + Md².", "K_rot = ½Iω².", "Rolling races decided by I/MR²."], "reqs": ["Mass distribution and axis.", "Parallel-axis shift if off-center.", "Rolling constraint if applicable."], "stds": ["I in kg·m².", "Standard formulas cited per shape."], "cites": ["Taylor JR. Classical Mechanics. University Science; 2005.", "Halliday D et al. Fundamentals of Physics. 12th ed. Wiley; 2021."], "demo": "#!/usr/bin/env python3\n\"\"\"Rolling race: acceleration factor 1/(1+I/MR²).\"\"\"\ndef factor(k):\n    return 1/(1+k)\nfor name, k in [(\"sphere\", 0.4), (\"disk\", 0.5), (\"hoop\", 1.0)]:\n    print(f\"  {name:7s}: a = {factor(k):.3f}·g·sinθ\")\n"}, {"tier": "Compounded", "g": "Statics", "title": "Static Equilibrium", "desc": "Equilibrium needs ΣF = 0 AND Στ = 0 - force balance plus torque balance, about any origin. Structures stand by it: bridges, buildings, cranes. Stability adds a third question: does it return after a nudge (stable), topple (unstable), or stay (neutral)?\nCenter of gravity must project within the support base - the toppling criterion. Ladders, cantilevers, and arches are the classic problems; indeterminate structures need elasticity (beyond statics).", "how": "Write ΣF_x = ΣF_y = 0 and Στ = 0 about a smart origin (kills unknowns). Solve for reactions. Check stability: CG over base, and perturb mentally. For ladders include friction at the foot; for indeterminate cases add elastic deformations.", "keys": ["ΣF = 0 and Στ = 0 both required.", "Torque balance about any origin.", "CG over base: the stability rule.", "Ladders need foot friction.", "Indeterminate → add elasticity."], "reqs": ["All forces and their lines of action.", "Origin choice for torques.", "Support conditions."], "stds": ["Reactions in N / N·m.", "Friction limits checked."], "cites": ["Halliday D et al. Fundamentals of Physics. 12th ed. Wiley; 2021.", "Taylor JR. Classical Mechanics. University Science; 2005."], "demo": "#!/usr/bin/env python3\n\"\"\"Seesaw balance: m1·d1 = m2·d2.\"\"\"\ndef balance(m1, d1, m2):\n    return m1*d1/m2\nprint(f\"  30 kg at 2 m balances {balance(30, 2, 60):.1f} m for 60 kg\")\n"}, {"tier": "Compounded", "g": "Oscillations", "title": "Simple Harmonic Motion", "desc": "F = -kx restores proportionally to displacement - the signature of SHM: x = A cos(ωt + φ), with ω = √(k/m), T = 2π√(m/k). Springs, pendulums (small angle), LC circuits, molecular vibrations - ubiquitous because any stable equilibrium looks harmonic for small displacements.\nEnergy sloshes between K and U at twice the motion frequency; velocity leads displacement by 90°. SHM is the linear approximation underlying all of vibration physics - and quantum oscillators.", "how": "Identify the restoring constant (k from F = -kx linearization). Compute ω = √(k/m_eff). Write x(t) from initial conditions (A, φ). Use energy E = ½kA² for amplitude questions. Check small-displacement validity.", "keys": ["F = -kx defines SHM.", "x = A cos(ωt + φ); ω = sqrt(k/m).", "Any stable equilibrium ≈ harmonic for small motion.", "E = ½kA²; energy sloshes K↔U.", "The universal vibration model."], "reqs": ["Linear restoring force.", "Effective mass and stiffness.", "Small-displacement regime."], "stds": ["ω in rad/s; f in Hz.", "Phase φ in radians."], "cites": ["Taylor JR. Classical Mechanics. University Science; 2005.", "French AP. Vibrations and Waves. Norton; 1971."], "demo": "#!/usr/bin/env python3\n\"\"\"SHM period from mass and stiffness.\"\"\"\nimport math\ndef T(m, k):\n    return 2*math.pi*math.sqrt(m/k)\nprint(f\"  m=0.5 kg, k=200 N/m: T = {T(0.5, 200):.3f} s\")\n"}, {"tier": "Compounded", "g": "Oscillations", "title": "The Pendulum: Harmonic Motion", "desc": "The simple pendulum: T = 2π√(L/g) for small angles - period independent of mass and (nearly) amplitude. Galileo timed his pulse with it; Huygens built clocks (1656); Foucault (1851) proved Earth's rotation with 67 meters of swinging bob.\nLarge angles need elliptic integrals (period lengthens); the physical pendulum uses I: T = 2π√(I/mgd). The seconds pendulum (~1 m, T = 2 s) once defined the meter's rivals.", "how": "Use T = 2π√(L/g) for θ < ~15°; correct upward for larger amplitudes. For compound pendulums use T = 2π√(I/mgd) about the pivot. Measure g by timing (precision gravimetry); demonstrate rotation with Foucault's plane precession.", "keys": ["T = 2π√(L/g), small angles.", "Independent of mass and amplitude (small).", "Foucault proved Earth's rotation (1851).", "Large angles: period lengthens.", "Physical pendulum: T = 2π√(I/mgd)."], "reqs": ["Length to center of mass.", "Small-angle check.", "Pivot friction minimized."], "stds": ["T in s; L in m.", "g = 9.81 m/s² unless measured."], "cites": ["Huygens C. Horologium Oscillatorium. 1673.", "Taylor JR. Classical Mechanics. University Science; 2005."], "demo": "#!/usr/bin/env python3\n\"\"\"Pendulum period vs length.\"\"\"\nimport math\ndef T(L, g=9.81):\n    return 2*math.pi*math.sqrt(L/g)\nfor L in (0.25, 1.0, 4.0):\n    print(f\"  L={L} m: T = {T(L):.2f} s\")\n"}, {"tier": "Compounded", "g": "Oscillations", "title": "Damped and Driven Oscillations", "desc": "Damping (F = -bv) decays amplitude exponentially: x = Ae^(-βt)cos(ω't); underdamped oscillates, critically damped returns fastest without overshoot (door closers, car suspensions), overdamped creeps. Q factor measures sharpness (energy stored/dissipated per cycle).\nDriving at ω_d: steady state follows the driver; amplitude peaks at resonance (ω_d ≈ ω₀) with width ∝ 1/Q. Resonance builds bridges down (Tacoma Narrows, 1940 - aeroelastic flutter) and tunes radios - the most consequential phenomenon in vibration engineering.", "how": "Classify damping: β < ω₀ under, = critical, > over. Design for critical in suspensions. For driven systems, compute the resonance curve; avoid operating at ω₀ in structures (or add damping). Use Q for selectivity (radio tuners) vs fast settling trade-offs.", "keys": ["Damping: under/critical/over.", "Critical returns fastest without overshoot.", "Resonance at ω_d ≈ ω₀; width ∝ 1/Q.", "Q = energy stored per cycle dissipated.", "Tacoma Narrows: resonance destroys."], "reqs": ["Damping coefficient.", "Drive frequency and amplitude.", "Q or β measured."], "stds": ["β, ω in rad/s; Q dimensionless.", "Resonance curves labeled."], "cites": ["French AP. Vibrations and Waves. Norton; 1971.", "Taylor JR. Classical Mechanics. University Science; 2005."], "demo": "#!/usr/bin/env python3\n\"\"\"Resonance amplitude vs drive frequency (Q=10).\"\"\"\ndef amp(w, w0=1.0, Q=10):\n    return 1/((1-(w/w0)**2)**2 + (w/(w0*Q))**2)**0.5\nfor w in (0.5, 0.9, 1.0, 1.1, 1.5):\n    print(f\"  ω/ω₀={w}: amplitude {amp(w):.2f}\")\n"}, {"tier": "Compounded", "g": "Waves", "title": "Waves on Strings", "desc": "Transverse waves: y(x,t) = A sin(kx - ωt + φ), speed v = √(T/μ) (tension over mass density). Standing waves quantize: fixed ends force nodes - L = nλ/2, f_n = nv/2L - the physics of guitars and violins.\nSuperposition creates beats (close frequencies), interference, and standing patterns. Energy travels at the group velocity; phase velocity is the crest speed - distinct in dispersive media.", "how": "Compute v = √(T/μ); find modes f_n = nv/2L for fixed ends. Tune instruments by tension (peg) - frequency ∝ √T. Analyze beats as superposition (|f₁-f₂| beat frequency). Distinguish phase vs group velocity in dispersive strings.", "keys": ["v = sqrt(T/μ).", "Fixed ends: L = nλ/2; f_n = nv/2L.", "Standing waves are superposition.", "Beats at |f₁ - f₂|.", "Phase vs group velocity differ when dispersive."], "reqs": ["Tension and linear density.", "Boundary conditions.", "Small-amplitude (linear) regime."], "stds": ["v in m/s; f in Hz.", "Modes numbered n = 1, 2, ..."], "cites": ["French AP. Vibrations and Waves. Norton; 1971.", "Halliday D et al. Fundamentals of Physics. 12th ed. Wiley; 2021."], "demo": "#!/usr/bin/env python3\n\"\"\"Guitar string harmonics (L=0.65 m, v=400 m/s).\"\"\"\ndef f(n, v=400, L=0.65):\n    return n*v/(2*L)\nfor n in (1, 2, 3, 4):\n    print(f\"  harmonic {n}: {f(n):.0f} Hz\")\n"}, {"tier": "Compounded", "g": "Waves", "title": "Mechanical Waves: Sound and Beyond", "desc": "Sound is longitudinal pressure waves: v = √(B/ρ) in fluids (343 m/s in air at 20 °C), faster in solids (√(Y/ρ)). Intensity ∝ A²; decibels compress the 10¹² range (β = 10 log(I/I₀), I₀ = 10⁻¹² W/m²).\nDoppler shifts frequency: approaching sources pitch up (f' = f·v/(v∓v_s)). Ultrasound images bodies and cleans; infrasound monitors volcanoes; sonar maps oceans. Standing sound waves make organ pipes (open: L = nλ/2; closed: L = nλ/4, odd n).", "how": "Compute speeds from moduli/density; intensity from amplitude. Apply Doppler with correct signs (source/observer motion). Design pipes: open-open all harmonics, closed-open odd only. Respect hearing limits (85 dB/8h) in noise problems.", "keys": ["v = sqrt(B/ρ) fluids; sqrt(Y/ρ) solids.", "Decibels: β = 10 log(I/I₀).", "Doppler: motion shifts pitch.", "Organ pipes: open all harmonics, closed odd.", "Ultrasound images; infrasound monitors."], "reqs": ["Medium properties (B, ρ).", "Source/observer velocities.", "Pipe end conditions."], "stds": ["v in m/s; β in dB.", "I₀ = 1e-12 W/m² reference."], "cites": ["French AP. Vibrations and Waves. Norton; 1971.", "Halliday D et al. Fundamentals of Physics. 12th ed. Wiley; 2021."], "demo": "#!/usr/bin/env python3\n\"\"\"Doppler shift for a passing siren.\"\"\"\ndef f_obs(f, vs, v=343):\n    return f*v/(v-vs)\nprint(f\"  approaching 30 m/s: {f_obs(440, 30):.0f} Hz\")\nprint(f\"  receding 30 m/s: {f_obs(440, -30):.0f} Hz\")\n"}, {"tier": "Compounded", "g": "Fluids", "title": "Fluid Statics: Pressure and Buoyancy", "desc": "Pressure P = F/A; hydrostatic P = P₀ + ρgh - dams thicken with depth. Pascal's principle transmits pressure undiminished (hydraulics multiply force by area ratio). Barometers (torricelli, 1643) weigh the atmosphere: 101.3 kPa.\nArchimedes: buoyant force equals weight of displaced fluid - floatation when ρ_body < ρ_fluid. Ships float by displacing their weight in water; balloons by displacing it in air. Surface tension adds capillary rise (h = 2γcosθ/ρgr).", "how": "Compute hydrostatic pressure with depth; apply Pascal for hydraulics (F₂ = F₁A₂/A₁). Check floatation: compare densities or weight vs buoyant force. Include surface tension for small scales (capillaries, droplets).", "keys": ["P = P₀ + ρgh.", "Pascal: pressure transmits; hydraulics multiply force.", "Archimedes: buoyancy = displaced weight.", "Float iff ρ_body < ρ_fluid.", "Capillarity matters at small scales."], "reqs": ["Fluid density.", "Depth/height.", "Displaced volume for buoyancy."], "stds": ["P in Pa; ρ in kg/m³.", "Atmospheric 101.3 kPa."], "cites": ["Halliday D et al. Fundamentals of Physics. 12th ed. Wiley; 2021.", "Batchelor GK. An Introduction to Fluid Dynamics. Cambridge; 1967."], "demo": "#!/usr/bin/env python3\n\"\"\"Buoyancy: will it float?\"\"\"\ndef floats(rho_body, rho_fluid=1000):\n    return rho_body < rho_fluid\nfor name, rho in [(\"ice\", 917), (\"wood\", 600), (\"steel\", 7800)]:\n    print(f\"  {name:6s}: {\"floats\" if floats(rho) else \"sinks\"}\")\n"}, {"tier": "Compounded", "g": "Frames", "title": "Non-Inertial Frames and Fictitious Forces", "desc": "Accelerating frames need fictitious forces: -ma_frame added to every mass. Rotating frames add centrifugal (mω²r outward) and Coriolis (-2mω×v, deflecting moving objects) - the latter steering hurricanes (counterclockwise NH) and Foucault pendulums.\nEinstein's equivalence principle: gravity is locally indistinguishable from acceleration - the seed of general relativity. Inertial frames are the ones where F = ma holds cleanly; everything else pays the fictitious-force tax.", "how": "Transform to the accelerating frame; add -ma₀ uniformly. In rotating frames add centrifugal and Coriolis terms. Predict Coriolis deflection (right in NH, left in SH). Invoke equivalence for gravitational problems (free-fall frames are locally inertial).", "keys": ["Fictitious forces fix F = ma in accelerating frames.", "Centrifugal: mω²r outward; Coriolis: -2mω×v.", "Coriolis steers weather and pendulums.", "Equivalence: gravity ≡ acceleration locally.", "Inertial frames need no corrections."], "reqs": ["Frame acceleration/rotation.", "Velocities in the rotating frame.", "Latitude for Coriolis magnitude."], "stds": ["Fictitious forces in N.", "ω in rad/s."], "cites": ["Taylor JR. Classical Mechanics. University Science; 2005.", "Einstein A. Ann Phys 1911;35:898-908."], "demo": "#!/usr/bin/env python3\n\"\"\"Coriolis acceleration at latitude φ.\"\"\"\nimport math\ndef coriolis(v, lat_deg):\n    return 2*7.292e-5*v*math.sin(math.radians(lat_deg))\nprint(f\"  v=50 m/s at 45°: a_c = {coriolis(50, 45)*1000:.2f} mm/s²\")\n"}, {"tier": "Compounded", "g": "Orbits", "title": "Central Forces and Orbits", "desc": "Central forces (F ∥ r) conserve angular momentum - motion stays planar, equal areas sweep. The effective potential U_eff = U(r) + L²/2mr² adds the centrifugal barrier; orbits follow from energy vs U_eff: bound (E < 0, elliptical for 1/r²), unbound (E ≥ 0).\nBertrand's theorem: only 1/r² and r² potentials give closed orbits for all bound energies - why planets retrace ellipses and springs retrace theirs. Scattering (Rutherford) is the unbound case.", "how": "Write U_eff with the centrifugal term; classify orbits by E vs U_eff minimum. For 1/r² derive conics (e from energy/angular momentum). Use the orbit equation or conserve E and L directly. Apply Rutherford scattering for Coulomb unbound trajectories.", "keys": ["Central force ⇒ planar motion, L conserved.", "U_eff = U + L²/2mr²: the barrier.", "E < 0 bound; E ≥ 0 unbound.", "Bertrand: only 1/r², r² close all orbits.", "Scattering = unbound central motion."], "reqs": ["Central potential U(r).", "Angular momentum L.", "Energy E."], "stds": ["U_eff in J; L in kg·m²/s.", "Eccentricity e dimensionless."], "cites": ["Goldstein H et al. Classical Mechanics. 3rd ed. Addison-Wesley; 2001.", "Taylor JR. Classical Mechanics. University Science; 2005."], "demo": "#!/usr/bin/env python3\n\"\"\"Orbit type from eccentricity.\"\"\"\ndef orbit(e):\n    return \"circle\" if e == 0 else (\"ellipse\" if e < 1 else (\"parabola\" if e == 1 else \"hyperbola\"))\nfor e in (0, 0.5, 1.0, 1.5):\n    print(f\"  e={e}: {orbit(e)}\")\n"}, {"tier": "Advanced", "g": "Analytical", "title": "Lagrangian Mechanics", "desc": "L = T - V: the Lagrangian. The Euler-Lagrange equations d/dt(∂L/∂q̇) - ∂L/∂q = 0 give motion in any generalized coordinates - constraints built in, no force diagrams. Bead on a wire, double pendulum, Atwood with massive pulley: choose coordinates, write T and V, turn the crank.\nCyclic coordinates (∂L/∂q = 0) give conserved momenta immediately - conservation laws fall out of symmetry (Noether's theorem in embryo). Lagrange (1788) made mechanics analytic; the principle of least action is its soul.", "how": "Choose generalized coordinates matching constraints; write T(q,q̇) and V(q); form L. Apply Euler-Lagrange per coordinate. Identify cyclic coordinates → conserved momenta. Check by recovering Newton in Cartesian coordinates.", "keys": ["L = T - V; Euler-Lagrange gives equations.", "Generalized coordinates absorb constraints.", "Cyclic coordinates → conserved momenta.", "No free-body diagrams needed.", "Least action is the deeper principle."], "reqs": ["Generalized coordinates.", "T and V in those coordinates.", "Constraint equations."], "stds": ["L in joules.", "Coordinates with dots for time derivatives."], "cites": ["Lagrange JL. Mécanique Analytique. 1788.", "Goldstein H et al. Classical Mechanics. 3rd ed. Addison-Wesley; 2001."], "demo": "#!/usr/bin/env python3\n\"\"\"Euler-Lagrange for 1D harmonic oscillator (symbolic check).\"\"\"\n# L = ½mq̇² - ½kq² → d/dt(mq̇) + kq = 0 → q̈ + (k/m)q = 0\nm, k = 1.0, 4.0\nimport math\nprint(f\"  ω = sqrt(k/m) = {math.sqrt(k/m):.1f} rad/s\")\n"}, {"tier": "Advanced", "g": "Analytical", "title": "The Principle of Least Action", "desc": "The action S = ∫L dt is stationary (δS = 0) for the true path - nature is economical. Euler-Lagrange follows from it; Fermat's least time (optics), Maupertuis, and Hamilton's principle are its faces.\nFeynman's path integral (1948) made it quantum: all paths contribute, the classical path dominates as ħ → 0. The principle unifies mechanics, optics, and field theory - the deepest formulation of dynamics.", "how": "Write S = ∫L dt between fixed endpoints; vary the path (δS = 0) to get Euler-Lagrange. Apply Fermat (least time) for optics problems - Snell's law falls out. Recognize stationary (not always minimum) - saddle actions exist.", "keys": ["δS = 0: the true path stationarizes action.", "S = ∫L dt.", "Euler-Lagrange follows from variation.", "Fermat's least time is the optical face.", "Feynman: all paths contribute quantumly."], "reqs": ["Lagrangian.", "Fixed endpoints.", "Variation calculus."], "stds": ["S in J·s.", "Stationary (not only minimal)."], "cites": ["Feynman RP. Rev Mod Phys 1948;20:367-387.", "Goldstein H et al. Classical Mechanics. 3rd ed. Addison-Wesley; 2001."], "demo": "#!/usr/bin/env python3\n\"\"\"Fermat: Snell law from least time (toy).\"\"\"\nimport math\ndef snell(n1, n2, t1_deg):\n    return math.degrees(math.asin(n1*math.sin(math.radians(t1_deg))/n2))\nprint(f\"  air→glass, 30°: {snell(1.0, 1.5, 30):.1f}°\")\n"}, {"tier": "Advanced", "g": "Analytical", "title": "Hamiltonian Mechanics", "desc": "H = Σ p q̇ - L: the Hamiltonian, usually total energy. Hamilton's equations (q̇ = ∂H/∂p, ṗ = -∂H/∂q) are first-order in phase space (q, p) - the natural arena: Liouville's theorem preserves phase volume, Poisson brackets {,} generate evolution.\nCyclic coordinates → conserved momenta is transparent here; canonical transformations simplify problems (action-angle variables solve integrable systems). Hamilton (1833) built the bridge to quantum mechanics (quantize the brackets).", "how": "Legendre-transform L → H (p = ∂L/∂q̇). Write Hamilton's equations; identify conserved momenta from cyclic coordinates. Use Poisson brackets {f,H} for time evolution of observables. Seek canonical transformations to action-angle for integrable systems.", "keys": ["H = Σ pq̇ - L, usually total energy.", "First-order equations in phase space.", "Liouville: phase volume preserved.", "Poisson brackets generate evolution.", "The bridge to quantum mechanics."], "reqs": ["Lagrangian or H directly.", "Canonical momenta defined.", "Phase-space coordinates."], "stds": ["H in joules.", "Brackets {q,p} = 1."], "cites": ["Hamilton WR. Phil Trans 1834;124:247-308.", "Goldstein H et al. Classical Mechanics. 3rd ed. Addison-Wesley; 2001."], "demo": "#!/usr/bin/env python3\n\"\"\"Hamiltonian of harmonic oscillator.\"\"\"\n# H = p²/2m + ½kq²; check energy at turning point\nm, k, A = 1.0, 4.0, 0.5\nE = 0.5*k*A*A\nprint(f\"  E = {E:.2f} J (all potential at turning point)\")\n"}, {"tier": "Advanced", "g": "Analytical", "title": "Canonical Transformations (Introduction)", "desc": "Canonical transformations (Q(q,p), P(q,p)) preserve Hamilton's form - new coordinates, same physics. Generating functions (F1-F4 types) produce them; the ultimate goal is coordinates where H is cyclic - then motion is trivial (action-angle variables).\nThe harmonic oscillator in action-angle: J = E/ω constant, angle advances uniformly - the template for perturbation theory (celestial mechanics runs on it). Symplectic integrators preserve the canonical structure numerically.", "how": "Propose a generating function; derive Q, P, and the new H (K = H + ∂F/∂t). Aim for cyclic coordinates (action-angle). Verify canonicity via Poisson brackets ({Q,P} = 1). Use symplectic integrators for long orbital simulations.", "keys": ["Preserve Hamilton's form in new coordinates.", "Generating functions produce them.", "Action-angle: the integrable-system solution.", "J = E/ω constant for the oscillator.", "Symplectic integrators for orbits."], "reqs": ["Generating function.", "Canonicity check.", "Integrability (enough constants)."], "stds": ["{Q,P} = 1 verification.", "Actions in J·s."], "cites": ["Goldstein H et al. Classical Mechanics. 3rd ed. Addison-Wesley; 2001.", "Arnold VI. Mathematical Methods of Classical Mechanics. 2nd ed. Springer; 1989."], "demo": "#!/usr/bin/env python3\n\"\"\"Action-angle for oscillator: J = E/ω.\"\"\"\nimport math\nE, omega = 2.0, 2.0\nprint(f\"  J = {E/omega:.2f} J·s (constant); angle advances at {omega:.1f} rad/s\")\n"}, {"tier": "Advanced", "g": "Rotation", "title": "Rigid Body Dynamics", "desc": "Rigid bodies rotate about moving axes: Euler's equations (I₁ω̇₁ - (I₂-I₃)ω₂ω₃ = τ₁, ...) in the body frame, with the inertia tensor encoding mass distribution. Torque-free motion: the polhode rolls on the herpolhode - Poinsot's geometric construction.\nThe tennis-racket (Dzhanibekov) effect: rotation about the intermediate axis is unstable - flips periodically. Euler's angles (φ, θ, ψ) orient the body; gyroscopes and satellites live here.", "how": "Write the inertia tensor (principal axes diagonalize it). Apply Euler's equations in the body frame; conserve L and E for torque-free motion. Identify the intermediate axis - avoid it for stable satellite spin. Use Euler angles for orientation kinematics.", "keys": ["Euler's equations in the body frame.", "Inertia tensor; principal axes diagonalize.", "Intermediate-axis rotation is unstable (Dzhanibekov).", "Torque-free: L and E conserved.", "Euler angles orient the body."], "reqs": ["Inertia tensor.", "Body-frame torques.", "Principal moments ordered."], "stds": ["Moments in kg·m².", "Euler-angle convention stated."], "cites": ["Goldstein H et al. Classical Mechanics. 3rd ed. Addison-Wesley; 2001.", "Taylor JR. Classical Mechanics. University Science; 2005."], "demo": "#!/usr/bin/env python3\n\"\"\"Intermediate-axis instability check.\"\"\"\nI = (1.0, 2.0, 3.0)\nmid = sorted(I)[1]\nprint(f\"  moments {I}: intermediate = {mid} -> rotation about it flips\")\n"}, {"tier": "Advanced", "g": "Rotation", "title": "Euler Angles and Tops", "desc": "Euler angles (φ precession, θ nutation, ψ spin) orient rigid bodies - the z-x-z convention standard. The symmetric top (I₁ = I₂ ≠ I₃): steady precession without nutation is possible; fast tops sleep (θ → 0); slow tops nod.\nGyroscopic stabilization: bicycle wheels, rifle bullets, satellites - angular momentum resists reorientation. Gyrocompasses find north from Earth's rotation; MEMS gyros navigate phones.", "how": "Set up Euler angles per convention; write L and E for the symmetric top. Find steady precession conditions (relation among φ̇, θ, ψ̇); check stability (fast top sleeps). Apply to gyroscopes: torque ⊥ L gives precession Ω = τ/L.", "keys": ["φ, θ, ψ: precession, nutation, spin.", "Symmetric top: I₁ = I₂ ≠ I₃.", "Fast tops sleep; slow tops nod.", "Gyroscopes resist reorientation.", "Ω = τ/L: the precession rate."], "reqs": ["Euler-angle convention.", "Principal moments.", "Torque direction vs L."], "stds": ["Angles in radians.", "Precession rates in rad/s."], "cites": ["Goldstein H et al. Classical Mechanics. 3rd ed. Addison-Wesley; 2001.", "Taylor JR. Classical Mechanics. University Science; 2005."], "demo": "#!/usr/bin/env python3\n\"\"\"Gyroscope precession rate.\"\"\"\ndef Omega(tau, L):\n    return tau/L\nprint(f\"  τ=0.1 N·m, L=2 kg·m²/s: Ω = {Omega(0.1, 2):.3f} rad/s\")\n"}, {"tier": "Advanced", "g": "Oscillations", "title": "Coupled Oscillators and Normal Modes", "desc": "Coupled oscillators exchange energy: two pendulums linked by a spring beat energy back and forth. Normal modes - coordinates oscillating at single frequencies - diagonalize the system: symmetric (in phase) and antisymmetric (out of phase) for the pair.\nMolecules vibrate in normal modes (CO2: symmetric stretch, antisymmetric, bend - IR/Raman activity from symmetry); buildings and bridges have modal frequencies to avoid. N coupled oscillators → N normal modes, the basis of phonon physics.", "how": "Write coupled equations; find normal coordinates diagonalizing M and K matrices (eigenvalue problem). Identify mode symmetries for selection rules (molecular vibrations). Design structures so drive frequencies avoid modal frequencies.", "keys": ["Normal modes: single-frequency coordinates.", "Beats = energy exchange between modes.", "N oscillators → N normal modes.", "Molecular vibrations are normal modes.", "Eigenvalue problem diagonalizes the system."], "reqs": ["Mass and stiffness matrices.", "Coupling terms.", "Boundary conditions."], "stds": ["Mode frequencies in rad/s or Hz.", "Eigenvectors normalized."], "cites": ["French AP. Vibrations and Waves. Norton; 1971.", "Goldstein H et al. Classical Mechanics. 3rd ed. Addison-Wesley; 2001."], "demo": "#!/usr/bin/env python3\n\"\"\"Two coupled pendulums: mode frequencies.\"\"\"\nimport math\nw0, wc = 2.0, 0.5  # natural, coupling\nprint(f\"  symmetric: {w0:.2f} rad/s; antisymmetric: {math.sqrt(w0**2+2*wc**2):.2f} rad/s\")\n"}, {"tier": "Advanced", "g": "Chaos", "title": "Chaos in Classical Systems", "desc": "Deterministic chaos: the double pendulum, driven Duffing oscillator, and three-body problem are perfectly deterministic yet unpredictable - sensitive dependence (Lyapunov exponents > 0) amplifies ignorance exponentially. Laplace's demon dies on measurement precision.\nPhase space reveals order within chaos: strange attractors (Lorenz), Poincaré sections, period-doubling routes (Feigenbaum). Chaos is not randomness - it is constrained unpredictability, and it bounds weather forecasting (~2 weeks).", "how": "Integrate with sensitive-dependence tests (perturb initial conditions); compute Lyapunov exponents. Plot Poincaré sections to reveal structure; measure fractal dimension of attractors. Distinguish chaos (deterministic, bounded, aperiodic) from noise (stochastic).", "keys": ["Deterministic yet unpredictable.", "Sensitive dependence: Lyapunov > 0.", "Strange attractors have fractal structure.", "Period-doubling route (Feigenbaum).", "Bounds weather prediction."], "reqs": ["Nonlinear equations of motion.", "Long-time integration.", "Perturbation tests."], "stds": ["Lyapunov exponents in 1/s.", "Attractor dimensions stated."], "cites": ["Lorenz EN. J Atmos Sci 1963;20:130-141.", "Strogatz SH. Nonlinear Dynamics and Chaos. 2nd ed. Westview; 2014."], "demo": "#!/usr/bin/env python3\n\"\"\"Lyapunov divergence: separation grows as e^(λt).\"\"\"\nimport math\ndef sep(t, lam=0.5, d0=1e-9):\n    return d0*math.exp(lam*t)\nfor t in (10, 20, 30):\n    print(f\"  t={t}s: separation {sep(t):.2e} m\")\n"}, {"tier": "Advanced", "g": "Relativity", "title": "Special Relativity as Mechanics Extended", "desc": "When v → c, mechanics extends: time dilates (Δt = γΔt₀), lengths contract (L = L₀/γ), simultaneity relativizes - all from Einstein's 1905 postulates (physics same in inertial frames; c constant). γ = 1/√(1-v²/c²).\nDynamics: p = γmv, E = γmc², E² = (pc)² + (mc²)² - mass is energy (E₀ = mc²). Newtonian mechanics is the v << c limit; classical mechanics hands off gracefully where it must.", "how": "Compute γ for the speed; apply dilation/contraction. Use relativistic energy-momentum (E² = (pc)² + (mc²)²) for collisions/decays. Check the low-speed limit recovers Newton (Taylor expand γ). Remember: c is the speed limit for information.", "keys": ["Postulates: relativity + constant c.", "γ = 1/sqrt(1-v²/c²).", "Time dilates; lengths contract.", "E = γmc²; E² = (pc)² + (mc²)².", "Newton is the v << c limit."], "reqs": ["Speed as fraction of c.", "Inertial frames.", "Invariant quantities identified."], "stds": ["β = v/c dimensionless.", "Energies in eV/J."], "cites": ["Einstein A. Ann Phys 1905;17:891-921.", "Taylor JR. Classical Mechanics. University Science; 2005."], "demo": "#!/usr/bin/env python3\n\"\"\"Gamma factor vs speed.\"\"\"\ndef gamma(beta):\n    return 1/(1-beta**2)**0.5\nfor b in (0.1, 0.5, 0.9, 0.99):\n    print(f\"  β={b}: γ = {gamma(b):.3f}\")\n"}, {"tier": "Advanced", "g": "Symmetry", "title": "Noether's Theorem", "desc": "Every continuous symmetry gives a conservation law: time translation → energy, space translation → momentum, rotation → angular momentum (Noether, 1918). Conservation laws are not accidents - they are symmetries' shadows.\nThe proof runs through the action: symmetries leave S invariant, producing conserved currents. It unifies the ad-hoc conservations of Newtonian mechanics and extends to field theory (charge conservation from gauge symmetry) - the deepest theorem in physics.", "how": "Identify the symmetry (translation, rotation, time shift); find the cyclic coordinate or invariant action. Read off the conserved quantity. Apply in Lagrangian/Hamiltonian form; extend the logic to fields (gauge → charge).", "keys": ["Symmetry ↔ conservation, one-to-one.", "Time → energy; space → momentum; rotation → L.", "Noether 1918.", "Proved via action invariance.", "Extends to fields (gauge → charge)."], "reqs": ["Lagrangian/action.", "Continuous symmetry identified.", "Boundary terms handled."], "stds": ["Conserved quantities with units.", "Symmetry group named."], "cites": ["Noether E. Nachr Ges Wiss Göttingen 1918:235-257.", "Goldstein H et al. Classical Mechanics. 3rd ed. Addison-Wesley; 2001."], "demo": "#!/usr/bin/env python3\n\"\"\"Symmetry-conservation dictionary.\"\"\"\ntable = {\"time translation\": \"energy\", \"space translation\": \"momentum\", \"rotation\": \"angular momentum\"}\nfor sym, cons in table.items():\n    print(f\"  {sym:17s} → {cons}\")\n"}, {"tier": "Advanced", "g": "Continuum", "title": "Continuum Mechanics Overview", "desc": "Solids and fluids as continua: stress tensors (force per area, 9 components), strain tensors (deformation), constitutive laws (Hooke for elastic solids, Navier-Stokes for Newtonian fluids). Cauchy's momentum equation generalizes F = ma to deformable media.\nApplications: structural engineering (beam theory from 3D elasticity), fluid dynamics (Navier-Stokes), biomechanics (tissue as continuum), geophysics (mantle flow). The mathematics is tensorial; the physics is Newton's laws per volume element.", "how": "Write stress/strain tensors; apply constitutive law (linear elastic: σ = C:ε; Newtonian fluid: τ = ηγ̇). Solve Cauchy's equation with boundary conditions. Reduce by symmetry (beam/plate/shell theories) for engineering use.", "keys": ["Stress and strain are tensors.", "Constitutive laws: Hooke, Navier-Stokes.", "Cauchy generalizes F = ma to continua.", "Beam/shell theories reduce dimensions.", "Tensor math, Newtonian physics."], "reqs": ["Material constitutive law.", "Boundary conditions.", "Symmetry reductions."], "stds": ["Stress in Pa; strain dimensionless.", "Tensor notation stated."], "cites": ["Malvern LE. Introduction to the Mechanics of a Continuous Medium. Prentice Hall; 1969.", "Batchelor GK. An Introduction to Fluid Dynamics. Cambridge; 1967."], "demo": "#!/usr/bin/env python3\n\"\"\"Beam deflection: δ = FL³/3EI (cantilever).\"\"\"\ndef deflect(F, L, E, I):\n    return F*L**3/(3*E*I)\nprint(f\"  F=1000N, L=2m, EI=1e6: δ = {deflect(1000, 2, 1e6, 1)*1000:.1f} mm\")\n"}];
function buildRecord(seed,topic,sig){
  var title=topic.title+(sig?' (Signature Edition)':'');
  var desc=topic.desc;
  if(sig)desc='Signature original treatment. '+desc;
  return {
    id:(sig?'JAH-CLMECS-':PREFIX)+String(seed).padStart(6,'0'),
    t:title, g:topic.g, name:title, title:title,
    description:desc,
    how_it_works:topic.how,
    key_points:topic.keys,
    requirements:topic.reqs,
    standards:topic.stds,
    citations:topic.cites,
    src:sig?'signature':'public-harvest',
    signature_label:sig?'Signature-generated original treatment - clearly labeled Signature-made and never presented as authentic public record.':'Public-harvest record - real, fact-checked domain knowledge.',
    ladder_rank:seed,
    ladder_tier:topic.tier.toLowerCase(),
    demo:{kind:'python',language:'python',program:topic.demo,
      note:'Working demonstration program for this record.'},
    _seed:seed
  };
}
function topicFor(seed,opts){
  opts=opts||{};
  var pool=TOPICS.filter(function(t){return !opts.field||t.tier===opts.field;});
  if(!pool.length)pool=TOPICS;
  var i=((seed-1)%pool.length+pool.length)%pool.length;
  return {topic:pool[i],index:TOPICS.indexOf(pool[i])};
}
function generate(seed,opts){
  var tf=topicFor(seed,opts);
  var sig=(opts&&opts.signature)||false;
  return buildRecord(tf.index+1,tf.topic,sig);
}
function validate(r){
  var e=[];
  if(!r||typeof r!=='object')return {ok:false,errors:['not an object']};
  var okId=new RegExp('^('+PREFIX.replace(/-/g,'\\-')+'|'+'JAH-CLMECS-'.replace(/-/g,'\\-')+')\\d{6}$').test(r.id||'');
  if(!okId)e.push('id');
  if(FIELDS.indexOf(capTier(r.ladder_tier))<0)e.push('tier');
  if(['public-harvest','signature'].indexOf(r.src)<0)e.push('src');
  if(!r.title)e.push('title');
  if(!r.description||r.description.length<40)e.push('description');
  if(!r.demo||!r.demo.program||r.demo.program.indexOf('print')<0)e.push('demo');
  return {ok:!e.length,errors:e};
}
function capTier(s){s=String(s||'');return s.charAt(0).toUpperCase()+s.slice(1);}
function driftCheck(record,sample){
  var dups=(sample||[]).filter(function(r){return r&&r.title===record.title&&r.ladder_tier===record.ladder_tier;});
  return dups.length?{ok:false,errors:['duplicate title+tier in archive sample']}:{ok:true,errors:[]};
}
var gen={version:'jahdb-classical-mechanics-1.0',generate:generate,validate:validate,driftCheck:driftCheck,fields:FIELDS};
if(typeof JAHDB!=='undefined'&&JAHDB.registerGenerator)JAHDB.registerGenerator('classical-mechanics',gen);
if(typeof module!=='undefined'&&module.exports)module.exports=gen;
})();
